import json
from datetime import datetime

from ssm_gcp.providers import DependencyManager
boto3_version, botocore_version, google_auth_version = DependencyManager.setup()
from ssm_gcp.utils.exception_mapper import step_handler
from ssm_gcp.exceptions import ServiceRequestError, ValidationException
from ssm_gcp.providers import (
    VERDICT_COMPLIANT,
    VERDICT_FAILED,
    VERDICT_NOT_TARGETED
)
from gcp_verify.report.package_result import report_package_result
from gcp_verify.report.verdict import (
    build_failure_message,
    build_not_targeted_message,
    build_retry_note,
    build_timeout_message
)

OPERATION = 'verifying the Distributor package installation'
VM_LOG_HEADER = '--- the end of what the virtual machine recorded ---'

_OUTCOMES = {
    VERDICT_COMPLIANT: "verified",
    VERDICT_FAILED: "not_installed",
    VERDICT_NOT_TARGETED: "not_targeted"
}

@step_handler
def assert_compliance(events, context):
    """Turn the last verdict into a result or into a failure.
    """
    verdict = events.get("verdict")
    detail = _detail_map(events.get("compliance_detail"))
    compliance_state = detail.get("compliance_state") or ""
    reason = detail.get("reason") or ""
    failure_detail = detail.get("failure_detail") or ""
    os_short_name = detail.get("os_short_name") or ""
    enforcement_log = detail.get("enforcement_log") or ""
    agent_log = detail.get("agent_log") or ""
    agent_log_state = detail.get("agent_log_state") or ""
    package_name = events.get("package_name") or ""
    report_update_time = events.get("report_update_time") or ""
    max_wait_minutes = _whole_number(
        events.get("max_wait_minutes"), "max_wait_minutes"
    )
    waited_minutes = _minutes_between(
        events.get("wait_started_at"), events.get("wait_ended_at")
    )

    aws_log = {
      "boto3_version": boto3_version,
      "botocore_version": botocore_version,
      "google_auth_version": google_auth_version,
      "verdict": str(verdict or ""),
      "compliance_state": compliance_state or "NONE",
      "compliance_state_reason": reason,
      "outcome": _OUTCOMES.get(str(verdict or ""), "timed_out"),
      "max_wait_minutes": str(max_wait_minutes),
      "waited_minutes": "" if waited_minutes is None else str(waited_minutes),
      "package_result": report_package_result(
          verdict,
          detail,
          package_name,
          events.get("package_version"),
          events.get("action"),
          context.get('global:REGION')
      )
    }

    if verdict == VERDICT_COMPLIANT:
        print(
            json.dumps(
                {
                    "operation": OPERATION,
                    "verdict": str(verdict),
                    "compliance_state": compliance_state,
                    "compliance_state_reason": reason,
                    "outcome": aws_log["outcome"]
                }
            )
        )
        return {
            "compliance_state": compliance_state,
            "verdict": str(verdict),
            "reason": reason,
            "aws_log": aws_log
        }

    if verdict == VERDICT_NOT_TARGETED:
        print(
            json.dumps(
                {
                    "operation": OPERATION,
                    "verdict": str(verdict),
                    "compliance_state_reason": reason,
                    "os_short_name": os_short_name,
                    "outcome": aws_log["outcome"],
                    "message": build_not_targeted_message(
                        os_short_name, package_name, reason
                    )
                }
            )
        )
        return {
            "compliance_state": compliance_state,
            "verdict": str(verdict),
            "reason": reason,
            "aws_log": aws_log
        }

    if verdict == VERDICT_FAILED:
        message = build_failure_message(
            reason,
            failure_detail,
            package_name,
            enforcement_log=enforcement_log,
            agent_log_state=agent_log_state,
            retry_note=build_retry_note(
                reason,
                report_update_time,
                first_checked_at=events.get("wait_started_at"),
                checked_at=events.get("wait_ended_at")
            )
        )
        error = ValidationException(message)
    else:
        message = build_timeout_message(
            reason, max_wait_minutes, package_name, waited_minutes=waited_minutes
        )
        error = ServiceRequestError(message)

    line = json.dumps(
        {
            "operation": OPERATION,
            "verdict": str(verdict or ""),
            "compliance_state": compliance_state,
            "compliance_state_reason": reason,
            "outcome": aws_log["outcome"],
            "report_update_time": report_update_time,
            "failure_detail": failure_detail,
            "package_result": aws_log["package_result"],
            "message": message
        }
    )
    _print_vm_log(enforcement_log or agent_log)
    print(line)

    raise error

def _print_vm_log(text):
    """Prints the virtual machine's log, which GetComplianceReport already cut to its end."""
    if not text:
        return

    print(VM_LOG_HEADER)
    print(text)

def _detail_map(value):
    """Given the recorded compliance detail, returns it as a mapping.
    """
    if isinstance(value, dict):
        return value

    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except ValueError:
            return {}
        if isinstance(parsed, dict):
            return parsed

    return {}

def _minutes_between(started, ended):
    """Given two step timestamps, returns the whole minutes between them, or None."""
    try:
        elapsed = datetime.fromisoformat(str(ended)) - datetime.fromisoformat(str(started))
    except (TypeError, ValueError):
        return None
    return max(int(elapsed.total_seconds() // 60), 0)

def _whole_number(value, name):
    """Given a step input, returns it as an int or raises naming it."""
    try:
        return int(str(value).strip())
    except (TypeError, ValueError):
        raise ValidationException(
            f"The {name} input must be a whole number."
        )
